// ---- Custom metrics: one Trend per endpoint, so p95 doesn't blend ----
const addToCartDuration = new Trend('add_to_cart_duration', true);
const checkoutDuration = new Trend('checkout_duration', true);
const checkoutWaiting = new Trend('checkout_waiting', true);   // server think time
const checkoutConnecting = new Trend('checkout_connecting', true); // TCP connect
const checkoutTLS = new Trend('checkout_tls', true);            // TLS handshake
const checkoutBlocked = new Trend('checkout_blocked', true);    // time queued waiting for a connection

export const options = {
  stages: [
    { duration: '30s', target: 50 },
    { duration: '30s', target: 100 },
    { duration: '30s', target: 150 },
    { duration: '30s', target: 200 },
    { duration: '30s', target: 300 },
    { duration: '30s', target: 400 },
    { duration: '10s', target: 500 },
    // // { duration: '30s', target: 150 },
    // { duration: '30s', target: 0 },

  ],
  thresholds: {
    checkout_duration: ['p(95)<3000'], // flips the check to fail loudly if p95 crosses 3s
  },
};

export default function () {
  const token = tokens[(exec.vu.idInTest - 1) % tokens.length];
  const product = items[Math.floor(Math.random() * items.length)];

  const params = {
    headers: {
      "Content-Type": "application/json",
      Cookie: `user_token=${token}`,
    },
  };

  // ---- Add item ----
  let res = http.post(
    `${BASE_URL}/add_to_cart`,
    JSON.stringify({
      resid: "6a5792fd6029a288631d51f8",
      userid: "",
      item: product.item,
      ress_name: "new kirana",
      qty: 1,
      item_id: product.item_id,
      price: product.price,
      replace: false
    }),
    { ...params, tags: { name: 'add_to_cart' } }
  );
  if (res.status != 200) {
    console.log(`VU ${exec.vu.idInTest} add failed ${res.status} ${res.body}`);
}
  addToCartDuration.add(res.timings.duration);

  check(res, {
    "add_to_cart: status 200": r => r.status === 200,
  });
  const body = JSON.stringify({
  coordinates: {"long":78.470354,"latt":17.452852},
  // other fields...
  });
  // ---- Checkout ----
  res = http.post(
    `${BASE_URL}/store_orders`,
    body,
    { ...params, tags: { name: 'store_orders' } }
  );
  const data=res.json()
  if (data.success && data.id) {
    console.log(`ORDER_ID:${data.id}`);
  }
  
  checkoutDuration.add(res.timings.duration);
  checkoutWaiting.add(res.timings.waiting);
  checkoutConnecting.add(res.timings.connecting);
  checkoutTLS.add(res.timings.tls_handshaking);
  checkoutBlocked.add(res.timings.blocked); // time spent waiting for a free connection in the pool

  check(res, {
    "checkout: status 200": r => r.status === 200,
  });

  // Log detail on anything slow so you can see WHERE the time went, not just that it was slow
  if (res.timings.duration > 2000) {
    console.log(
      `SLOW checkout vu=${exec.vu.idInTest} total=${res.timings.duration.toFixed(0)}ms ` +
      `blocked=${res.timings.blocked.toFixed(0)}ms connecting=${res.timings.connecting.toFixed(0)}ms ` +
      `tls=${res.timings.tls_handshaking.toFixed(0)}ms waiting=${res.timings.waiting.toFixed(0)}ms ` +
      `status=${res.status}`
    );
  }

  // if (res.status !== 200) {
  //   console.log(`FAILED checkout vu=${exec.vu.idInTest} status=${res.status} body=${res.body} res=${JSON.stringify(res)}`);
  // }

  if (res.status !== 200) {
    console.log(`FAILED checkout vu=${exec.vu.idInTest} status=${res.status} body=${res.body}`);
  }

  // sleep(Math.random() * 4 + 2);
}